            samples: 4,
            inner: 10,
            duration_s: 5.0,
            suspended_s: 0.0,
            block_stats: BlockStats {
                blocks: 2,
                mean_ns: 24.0,
                ci95_ns: Some(1.0),
                lsc_ns: Some(2.0),
            },
            blocks: [23_500.0, 24_500.0]
                .into_iter()
                .map(|mean_ps| BlockSummary {
                    t_start_s: 0.0,
                    t_end_s: 0.05,
                    count: 2,
                    floor_ps: 20_000,
                    floor_q_ps: 20_000,
                    mean_ps,
                    max_ps: 30_000,
                    over_floor: 0,
                })
                .collect(),
            probes: Vec::new(),
            warmup_probes: 0,
